216	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
217	    @Override
218	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
219	        Owner owner = this.clinicService.findOwnerById(ownerId);
220	        if (owner != null) {
221	            Pet pet = owner.getPet(petId);
222	            if (pet != null) {
223	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
224	            }
225	        }
226	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
227	    }
228	
229	    /**
230	     * Resolves the city name to use for a newly created owner. The supplied city is
231	     * title-cased (each whitespace-separated word starts with an upper-case letter and the
232	     * remaining letters are lower-cased), for example {@code "new york"} becomes
233	     * {@code "New York"}. However, if an owner already exists in that city (matched ignoring
234	     * letter case), the existing owner's exact spelling of the city name is reused instead, so
235	     * that all owners in a city share a single canonical spelling.
236	     *
237	     * @param city the city supplied for the owner being created, may be {@code null}
238	     * @return the city name to store and return for the owner
239	     */
240	    private String resolveCity(String city) {
241	        if (city == null) {
242	            return null;
243	        }
244	        String existingCity = this.clinicService.findAllOwners().stream()
245	            .map(Owner::getCity)
246	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
247	            .findFirst()
248	            .orElse(null);
249	        if (existingCity != null) {
250	            return existingCity;
251	        }
252	        return toTitleCase(city);
253	    }
254	
255	    /**
256	     * Title-cases the given text so that each whitespace-separated word starts with an
257	     * upper-case letter and the remaining letters are lower-cased, for example
258	     * {@code "new york"} and {@code "NEW YORK"} both become {@code "New York"}. The original
259	     * spacing between words is preserved.
260	     *
261	     * @param value the text to title-case
262	     * @return the title-cased text
263	     */
264	    private static String toTitleCase(String value) {
265	        StringBuilder result = new StringBuilder(value.length());
266	        boolean startOfWord = true;
267	        for (int i = 0; i < value.length(); i++) {
268	            char ch = value.charAt(i);
269	            if (Character.isWhitespace(ch)) {
270	                startOfWord = true;
271	                result.append(ch);
272	            } else if (startOfWord) {
273	                result.append(Character.toUpperCase(ch));
274	                startOfWord = false;
275	            } else {
276	                result.append(Character.toLowerCase(ch));
277	            }
278	        }
279	        return result.toString();
280	    }
281	
282	    /**
283	     * Builds the customer code for a newly created owner, formatted as
284	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of
285	     * owners already registered in that city, zero-padded to four digits (e.g.
286	     * {@code 'LONDON-0007'}). Cities are matched ignoring letter case so the sequence is
287	     * consistent with the upper-cased prefix.
288	     *
289	     * @param city the city of the owner being created
290	     * @return the assigned customer code
291	     */
292	    private String nextCustomerCode(String city) {
293	        long ownersInCity = this.clinicService.findAllOwners().stream()
294	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
295	            .count();
296	        return city.toUpperCase() + "-" + String.format("%04d", ownersInCity + 1);
297	    }
298	
299	    /**
300	     * Counts how many existing owners share the given last name at this moment. The count is taken
301	     * over the owners already registered (excluding the owner currently being created, which has not
302	     * yet been persisted); last names are compared for exact equality.
303	     *
304	     * @param lastName the last name of the owner being created
305	     * @return the number of other owners that currently share the given last name
306	     */
307	    private int countNamesakes(String lastName) {
308	        return (int) this.clinicService.findAllOwners().stream()
309	            .filter(existing -> Objects.equals(existing.getLastName(), lastName))
310	            .count();
311	    }
312	
313	    /**
314	     * Determines whether, at the moment the owner is being created, another owner already shares
315	     * the same household &mdash; that is, an existing owner has both the same address and the same
316	     * city. Address and city are compared for exact equality, using the values resolved for the
317	     * owner being created (which has not yet been persisted).
318	     *
319	     * @param owner the candidate owner to check
320	     * @return {@code true} if an existing owner already has the same address and city
321	     */
322	    private boolean sharesHousehold(Owner owner) {
323	        return this.clinicService.findAllOwners().stream()
324	            .anyMatch(existing -> Objects.equals(existing.getAddress(), owner.getAddress())
325	                && Objects.equals(existing.getCity(), owner.getCity()));
326	    }
327	
328	    /**
329	     * Determines the locality of the owner being created, based on the given city. The city is
330	     * {@code "local"} if it is the single most common city among the existing owners at this moment
331	     * (before the owner being created is persisted); otherwise it is {@code "remote"}. Cities are
332	     * compared ignoring letter case. If there are no existing owners, or if two or more cities are
333	     * tied for the most common, there is no single most common city and the result is
334	     * {@code "remote"}.
335	     *
336	     * @param city the city of the owner being created, may be {@code null}
337	     * @return {@code "local"} or {@code "remote"}
338	     */
339	    private String determineLocality(String city) {
340	        if (city == null) {
341	            return "remote";
342	        }
343	        Map<String, Long> countsByCity = this.clinicService.findAllOwners().stream()
344	            .map(Owner::getCity)
345	            .filter(Objects::nonNull)
346	            .collect(Collectors.groupingBy(existing -> existing.toLowerCase(), Collectors.counting()));
347	        if (countsByCity.isEmpty()) {
348	            return "remote";
349	        }
350	        long max = Collections.max(countsByCity.values());
351	        List<String> mostCommon = countsByCity.entrySet().stream()
352	            .filter(entry -> entry.getValue() == max)
353	            .map(Map.Entry::getKey)
354	            .toList();
355	        if (mostCommon.size() == 1 && mostCommon.get(0).equals(city.toLowerCase())) {
356	            return "local";
357	        }
358	        return "remote";
359	    }
360	
361	    /**
362	     * Determines whether the maximum number of owners that may be registered on a single day has
363	     * already been reached. At most 20 owners may be created per day; the count is taken over the
364	     * owners whose registration date is today.
365	     *
366	     * @return {@code true} if 20 or more owners have already been registered today
367	     */
368	    private boolean isDailyRegistrationLimitReached() {
369	        LocalDate today = LocalDate.now();
370	        long ownersToday = this.clinicService.findAllOwners().stream()
371	            .filter(existing -> today.equals(existing.getRegistrationDate()))
372	            .count();
373	        return ownersToday >= 20;
374	    }
375	
376	    /**
377	     * Determines whether the city of the owner being created has already reached its capacity of
378	     * owners. At most 8 owners may be registered in a single city; the count is taken over the
379	     * existing owners whose city matches (ignoring letter case) the given city.
380	     *
381	     * @param city the city of the owner being created, may be {@code null}
382	     * @return {@code true} if the city already contains 8 or more owners
383	     */
384	    private boolean isCityCapacityReached(String city) {
385	        if (city == null) {
386	            return false;
387	        }
388	        long ownersInCity = this.clinicService.findAllOwners().stream()
389	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
390	            .count();
391	        return ownersInCity >= 8;
392	    }
393	
394	    /**
395	     * Determines whether an owner already exists that uses the same telephone number as the
396	     * given candidate. Telephone numbers are compared digits-only, so formatting characters
397	     * such as spaces, dashes and parentheses are ignored.
398	     *
399	     * @param owner the candidate owner to check
400	     * @return {@code true} if an owner with the same telephone number already exists
401	     */
402	    private boolean isDuplicateOwner(Owner owner) {
403	        String telephone = normalizeTelephone(owner.getTelephone());
404	        return this.clinicService.findAllOwners().stream()
405	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
406	    }
407	
408	    /**
409	     * Determines whether an owner already exists that uses the same email address as the
410	     * given candidate. Owners without an email address are never considered duplicates.
411	     * The comparison ignores letter case and surrounding or repeated whitespace.
412	     *
413	     * @param owner the candidate owner to check
414	     * @return {@code true} if an owner with the same email address already exists
415	     */
416	    private boolean isDuplicateEmail(Owner owner) {
417	        String email = normalize(owner.getEmail());
418	        if (email == null || email.isEmpty()) {
419	            return false;
420	        }
421	        return this.clinicService.findAllOwners().stream()
422	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
423	    }
424	
425	    /**
426	     * Normalizes a value for duplicate detection so that comparisons ignore letter case and
427	     * surrounding or repeated whitespace. Leading and trailing whitespace is stripped, any run
428	     * of internal whitespace collapses to a single space, and the result is lower-cased. For
429	     * example {@code "  John   Smith "} and {@code "John Smith"} both normalize to
430	     * {@code "john smith"}.
431	     *
432	     * @param value the value to normalize, may be {@code null}
433	     * @return the normalized value, or {@code null} if {@code value} is {@code null}
434	     */
435	    private static String normalize(String value) {
436	        if (value == null) {
437	            return null;
438	        }
439	        return value.strip().replaceAll("\\s+", " ").toLowerCase();
440	    }
441	
442	    /**
443	     * Normalizes a telephone number to digits only by stripping every non-digit character
444	     * (such as spaces, dashes and parentheses). This is used both to store telephone numbers
445	     * in a canonical form and to compare them for uniqueness, so that {@code "(613) 555-0100"}
446	     * and {@code "6135550100"} are treated as the same number.
447	     *
448	     * @param value the telephone number to normalize, may be {@code null}
449	     * @return the digits-only telephone number, or {@code null} if {@code value} is {@code null}
450	     */
451	    private static String normalizeTelephone(String value) {
452	        if (value == null) {
453	            return null;
454	        }
455	        return value.replaceAll("\\D", "");
456	    }
457	}
